package main
import "fmt"
type Progress struct{ percent int }
func NewProgress(p int)(*Progress,error){ if p<0||p>100{return nil,fmt.Errorf("percent: %d",p)}; return &Progress{p},nil }
func (p Progress) Percent()int{return p.percent}
func main(){p,_:=NewProgress(75);fmt.Println(p.Percent())}

package main
import ("fmt";"sync")
func main(){ var wg sync.WaitGroup; results:=make(chan int,2); for _,n:=range []int{70,100}{wg.Add(1);go func(v int){defer wg.Done();results<-v}(n)}; wg.Wait();close(results);for v:=range results{fmt.Println(v)} }
